WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (300::BIGINT, 'Las tareas son demandantes, pero es un excelente profesor. Además se aprende un montón si quiere.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c8a95eb628d89db56fa25a7446355978ef6bbbed0fdccb9c99da231bc30118da'::TEXT, ARRAY[1047]::BIGINT[]),
    (300::BIGINT, '40%: 3 proyectos, 30%: laboratorios 20%: 3 exámenes y 10: Exposiciones. Busque un buen equipo de trabajo, los proyectos son grandes y la mayoría de laboratorios son grupales. Ni se preocupe por los exámenes, aunque estudie no va a sacar buena nota, no da tiempo extra nunca y todo es presencial.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'c1646e27b9ea93ecb2a760f0eb1df2565108613a2522a15c910259c79ded627a'::TEXT, ARRAY[1154]::BIGINT[]),
    (300::BIGINT, 'Un profe super chill con el proyecto, el mae no le interesa lo que ocurra, mientras el cliente esté satisfecho, el mae pone nota alta. Definitivamente meta con él.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '796a4243fb614796d5533623b6bd6a8c1cb21ffcb816c8ebc1c0a69d59a31b5d'::TEXT, ARRAY[1165]::BIGINT[]),
    (300::BIGINT, 'Rodolfo es una persona excelente pero prepárese para ser autodidacta, cite correctamente en los proyectos y resuma las presentaciones o material dado en clase. Más allá de eso, las clases son super tranquilas y Rodolfo siempre brinda apoyo si lo necesita.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'a3df110e9c1c0bb65ec98b93d998ff1e966b8464212e90ca71ada26e9b858649'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'El curso es crear un sistema real para un cliente externo o él mismo, se deja de recibir clases a partir de semana 5 más o menos, pues en ese tiempo debemos estar desarrollando el proyecto. El profe sabe mucho y siempre da muy buenas retroalimentaciones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-07-02T00:00:00+00:00'::TIMESTAMPTZ, '1f3bfdd78dfcee78af4ed24facefd12aff366017150e1912ace529b9b2b5bd5b'::TEXT, ARRAY[1159]::BIGINT[]),
    (300::BIGINT, 'Igual que los comentarios anteriores, crear un sistema a un cliente real. Lo único complicado es la entrega de los informes, ya que no es muy explicito con la información. Los proyectos casi siempre los busca el profe'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5fd6e066713c43db4f0adb372806cc31b2e75ed3a3fba2ee14659ecca50e0706'::TEXT, ARRAY[1159]::BIGINT[]),
    (300::BIGINT, 'El mae es una teja, explica bien, da información clara y concisa, las clases son chill y los proyectos no son complicados. Lo único es los exámenes que son algo difíciles y las entregas de los trabajos es algo estricto, si puso una fecha es muy difícil que lo cambie.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-06-07T00:00:00+00:00'::TIMESTAMPTZ, '2ab3ea6e87588f8b8f862db7aaa60e04ca97736bb081d8fc87f9075328c268f7'::TEXT, ARRAY[1154]::BIGINT[]),
    (300::BIGINT, 'El curso es crear un sistema real para un cliente externo o él mismo, debe de seguir la metodología ágil que él enseña y tener disciplina, paciencia y trabajar bien con su equipo de trabajo pues esto le afectaría directamente en el desarrollo del proyecto por el componente de entregar informes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '395c8a84123d877ab6294a5d2f8cdfa39254c41293bc8bcc2704938d53fa49b2'::TEXT, ARRAY[1159]::BIGINT[]),
    (300::BIGINT, 'Rodolfito es buena people, no deja muchas asignaciones, los proyectos que deja son realizables. Es clase magistral donde uno lo escucha hablar y resume en el cuaderno porque no hay presentaciones. No tiene problema en explicarle algo de primer semestre para que entienda algo de este curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'a62bb9d496ea22786cc30d89885ca61fbb264f3d1aff24a1caf09a5f1039b81b'::TEXT, ARRAY[1154]::BIGINT[]),
    (300::BIGINT, 'Muy buen profe. Buenas explicaciones y está siempre dispuesto a aclarar dudas. El curso es un toque pesado pero con él se puede llevar bien entregando las evaluaciones (que no tienden a ser complicadas). Muy recomendado para primer ingreso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0862b8b9829b069c63f1b8dd45384fffb9251719ce001aa646b1ad7ad3687268'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Buen profe para llevar este curso, es bastante comprensivo con la disponibilidad de tiempo de cada uno y que es la primera vez que muchos hacemos desarrollo ágil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7692f65860d6cfbcb21f4fe6f6651f4c4a5f945596ca63805cd3418fce916b20'::TEXT, ARRAY[1159]::BIGINT[]),
    (300::BIGINT, 'Un curso muy de chill, nada mas consiga un buen equipo de trabajo y se saca facil, porque todas las evaluaciones son grupales. Las clases son improvisadas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'de1475dc53f2e5bec31c05fd1b1faefccc4c36df9806cdda308e1ee9c66e0b64'::TEXT, ARRAY[1047]::BIGINT[]),
    (300::BIGINT, 'Rodo es un crack, pero es una mente en su propio mundo, el mae tiene días que alchile se vuela y da unas superclases y otros que no tanto, muy flexible y explica bien, es medio sarcástico entonces tiene que saber como preguntar y que preguntar. Super disponible para consultas, ayuda mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2023-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'bdf709008cab24ecf2d8ea1ea712f3e62b10bb2293e3d9aaabd3ed3cc65535bc'::TEXT, ARRAY[1047]::BIGINT[]),
    (300::BIGINT, 'El profe sacaba tardes enteras para ayudarme a mí y mi equipo con las varas, siempre estuvo dispuesto a ayudar y orientarnos. Además el mae es super flexible con las entregas, nunca se pone en varas. De los mejores profes que he tenido. PD: no usen ubuntu, lo odia jaja'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-09T00:00:00+00:00'::TIMESTAMPTZ, '1c8ea6ca3923dfef198fc55c327d753efc8fc169cefbc4df766a3e312113aef8'::TEXT, ARRAY[1159]::BIGINT[]),
    (300::BIGINT, 'Si un examen trae parte programada, debes saber la sintaxis de memoria, tanto los proyectos como las tareas pueden ser extensas. Con respecto a las lecturas, estaban completamente desincronizadas con la materia en clase. Hubo clases donde se notó que no tenía nada preparado.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '5309c79c2c9ae5c51fe7c08da8c62a046cea6caa22e84ec21c529bbb8bda714f'::TEXT, ARRAY[1154]::BIGINT[]),
    (300::BIGINT, 'Buen profe, explica claro, sus evaluaciones no son muy complejas y siempre está dispuesto a ayudar. Llevaría un curso con él nuevamente.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-12-05T00:00:00+00:00'::TIMESTAMPTZ, '8aecbf66533ec7bb527333e92daa414b1a17b8894d33b9120485c9af3d33f352'::TEXT, ARRAY[1154]::BIGINT[]),
    (300::BIGINT, 'Yo lleve FOC con él de forma virtual en el I semestre del 2022 y la verdad me pareció un profe bien/normal, había bastantes trabajos y tenían su dificultad, pero tampoco súper matados como con otros profes. Si usted le preguntaba por ayuda, él lo ayudaba sin importar la hora.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-11-14T00:00:00+00:00'::TIMESTAMPTZ, '3c2a5071761a4b3b799e2f6f3455efbf46dba6b2e95c0655e4e2647747032d08'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'El peor, el mae quiere que ud pase 24/7 desarrollando todos las labores del curso, nunca se le queda bien con nada porque uno tiene que adivinar hasta las palabras que él quiere que uno use, siempre que pone un mensaje en el chat es sólo para regaños o quejas generales, se nota que odia dar clases.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-08-23T00:00:00+00:00'::TIMESTAMPTZ, '3746c7234ab40068d2f4d39f489525a99587ccb32c2b827d72743af7027b957b'::TEXT, ARRAY[1159]::BIGINT[]),
    (300::BIGINT, 'El profe parece que siempre anda apurado, llega chorrea (no la da, solo tira contra la pared toda la materia al rapidón y ya) el curso y uno solo queda confundido, luego andarle preguntando es complicado porque el mae hasta que voltea los ojos porque claramente le da pereza que uno le haga preguntas'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'ddf23ba54e7178c87c7f4caf0769e3b51eb6126378d2f79f446d3f20e1ca00c3'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Debería dar el curso asincrónico, cuando da clases parece un correcaminos y hace caras de asco cuando le preguntan algo. Definitivamente el TEC se centra únicamente en contratar ingenieros y no en profesores reales, el curso se pasa fácil con un buen equipo de trabajo y dedicarle muchas horas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-02-25T00:00:00+00:00'::TIMESTAMPTZ, '05ff8a10687250fd1f81f59481c45c6b5ff474e682293511ee129cfcfd6a6300'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Buen profe cuando le interesa serlo. Sus trabajos y evaluaciones están muy por encima de lo visto en clase, sin ayuda externa hacer los trabajos es casi imposible.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '02e10aca720466e597a9a6f45148c24efb29676b9ef5554ec99b8d2402837305'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Las clases son bastante sencillas. Son puro trabajo grupal pero nunca son verdaderamente dificiles. Sabe mucho de lo que habla y cae bien, entonces las clases tienen un ambiente agradable. Evalúa muy claramente y es ordenado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'baa76850dcfbd1f0d9d35ae7565f7070e3b1efc9784515ffc524169217bf216d'::TEXT, ARRAY[1156]::BIGINT[]),
    (300::BIGINT, 'El curso con el profesor se reduce a investigar de temas y exponerlos en clase con los compañeros. El profe hace comentarios al respecto (y a veces se pega unos rants que son muy acertados con la realidad). El profe es muy pura vida y sabe mucho de lo que está hablando. Buen profesor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '2445b3af571fc9ec9f91494dbc33a6249aca5abd0bfc8fb603557e9a6db92966'::TEXT, ARRAY[1156]::BIGINT[]),
    (300::BIGINT, 'En SJ no hay de otra, solo da este profe, prepárese para que el profesor piense que solamente lleva su curso y que deje tareas con tiempo de entrega de 2 días o menos. Además de que cuando responde dudas no es claro, se va por las ramas. Sinceramente nunca volveré a llevar otro curso con él.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3d8b12c5cd886fc627271c45838c24b43dc7955aab4a04bb3bacaf25650b9388'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'La mitad de las clases son asincrónicas y le toca a uno enseñarse las cosas. Prácticamente todas las semanas deja un trabajo, la mayoría en grupo. En general se pasa fácil y si uno le pregunta contesta pero cuesta que le diga directamente la respuesta.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, '15d24ab3a18721767039a07bbe7b763f8ab3df5a8bb5e8e66c18f9cb7f45f70e'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Es de lo peor de la escuela de computación, todo lo hace asincrónico y cualquier duda ni disimula en hacer una cara de asco. Pésimo profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'fba78a7669825484e7ab5cb0f5ddbb29a9953203bc485cf9817d3035f61e677a'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Es calidad de profe, solo que le molesta que los alumnos no vayan a clases. Sin embargo el profe siempre esta dispuesto ayudar y que hace el curso muy dinámico, como actividades grupales y exposiciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-02-15T00:00:00+00:00'::TIMESTAMPTZ, 'ce4c163a635d06654b2e2a322cd325af8c78ebc60bce9ffb96b4489ba1f96e35'::TEXT, ARRAY[1139]::BIGINT[]),
    (300::BIGINT, 'En lo personal yo matriculé el curso pensando que ibamos a aprender cosas tipo cómo funcionan los mapas, cómo programarlos y hacer cosas interesantes, etc. Pero pasamos todo el semestre usando QGis y montando capas. Facilisimo de pasar eso sí, pero no se aprende nada interesante :('::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '8e181e2ab95cb36958f4dae74a6c55904595865dfd315a0847db7896128e9df1'::TEXT, ARRAY[1129]::BIGINT[]),
    (300::BIGINT, 'Una decepción de curso, esperaba que por lo menos diera clases, pero solo nos dio cerca de 8 clases, las demás se las tomó para ponernos a trabajar o que viéramos vídeos o realizáramos actividades por fuera. No tiene nada preparado, no muestra interés. Solo se relaciona con su grupo de conocidos.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2020-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'f1e46e11f862b72e88c7c25614b4c4ec5d656db00b09f7ad2f959cb575509c70'::TEXT, ARRAY[1139]::BIGINT[]),
    (300::BIGINT, 'Semana 13 y sigo sin entender a que vamos a clases, mejor las diera todas asincronicas y ya. Vamos a escuchar a los compañeros exponer y oír las historias del profe y su vida. Aburridisimo'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-11-23T00:00:00+00:00'::TIMESTAMPTZ, '5b2d1419d09d87a32b51e888e81e0e3335c9c1fb40c6fd1ea88ea72197c9c502'::TEXT, ARRAY[1129]::BIGINT[]),
    (300::BIGINT, 'De esos profesores que ponen a los estudiantes a exponer para que "aprendamos". Al final las clases son una perdida de tiempo y si se le pregunta algo ni disimula que le molesta que le pregunten. A todo lo anterior agreguele que tiene sus favoritismos con estudiantes que conoce desde antes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas']::TEXT[], '2020-10-04T00:00:00+00:00'::TIMESTAMPTZ, 'c629c1800b305f824c713824d889cd28d9517bfb0220f6a04afd8d204a55876b'::TEXT, ARRAY[1129]::BIGINT[]),
    (300::BIGINT, 'La clase cómo tal no es díficil, pero es un desperdicio de tiempo, el profesor se pone a conversar y contar anécdotas cómo si estuviera en un parque tomando café además de que siempre hay que exponer los trabajos, entonces hay clases que literal dan sueño.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-24T00:00:00+00:00'::TIMESTAMPTZ, '61a503c0ab8db854e137ee221536cca4eb9a05b0e9c60ed9133173ce6336f4cd'::TEXT, ARRAY[1129]::BIGINT[]),
    (300::BIGINT, 'Cuando se le pregunta algo, el profe responde casi al instante. El problema es que vimos muy poca materia. Deja pocos trabajos, y los tiempos de entrega son accesibles. Se pasa fácil, pero no sé aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Brinda apoyo']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '3c0a222c7dd84561973afc9d059a4f2be4ffbb144ee0a325b8dfc40a2f8a6287'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '3f49501cfaae812dafb4b49ee3e5eba358727f1d649a8a6272197fb7681051a2'::TEXT, ARRAY[1017]::BIGINT[]),
    (300::BIGINT, 'Es un buen profesor y se interesa por el estudiante'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2019-02-07T00:00:00+00:00'::TIMESTAMPTZ, '208816e83cb66b3eba4f5d11cb99caaa098beebaeff8000c4d2d5654ad2e7109'::TEXT, ARRAY[1030]::BIGINT[]),
    (300::BIGINT, 'Es muy buen profe, le interesa que el alumno aprenda. Ayuda cuando uno lo necesita'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ebbf3c07ef15d7edc91ada43211acfd0ed7dd1d3bc29f764ed930f630028666d'::TEXT, ARRAY[1047]::BIGINT[]),
    (300::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '30d7447968ec9338c6c30eec6eec4cb0066c2fce2fb5a40d230a943f65512b54'::TEXT, ARRAY[1037]::BIGINT[]),
    (300::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '2dd901e78dd1f88c60b6cf23adbdb1bc6fa1c87603d2cad09674976690fc02c7'::TEXT, ARRAY[1037]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
